package com.grifplot.libros;
import android.content.*;import android.os.*;import android.net.*;import java.io.*;import java.nio.*;import java.nio.channels.*;import java.util.regex.*;
/* Reads ordinary uncompressed PDF Info dictionaries without loading a whole PDF.
   Object streams or encrypted metadata fall back to filename/manual catalog fields. */
final class PdfMetadata {
 static String[] read(Context ctx,String uri){try(ParcelFileDescriptor pfd=ctx.getContentResolver().openFileDescriptor(Uri.parse(uri),"r")){if(pfd==null)return new String[]{"","",""};try(FileInputStream in=new FileInputStream(pfd.getFileDescriptor())){FileChannel c=in.getChannel();long size=c.size();int limit=262144;byte[] head=new byte[(int)Math.min(size,limit)];ByteBuffer buffer=ByteBuffer.wrap(head);while(buffer.hasRemaining()&&c.read(buffer)>0){}String s=new String(head,"ISO-8859-1");if(size>limit){c.position(Math.max(limit,size-limit));ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] chunk=new byte[8192];int n;while((n=in.read(chunk))>0)out.write(chunk,0,n);s+="\n"+out.toString("ISO-8859-1");}Matcher ref=Pattern.compile("/Info\\s+(\\d+)\\s+(\\d+)\\s+R").matcher(s);String num="",gen="";while(ref.find()){num=ref.group(1);gen=ref.group(2);}if(num.isEmpty()||s.contains("/Encrypt "))return new String[]{"","",""};Matcher obj=Pattern.compile("(?s)(?:^|[\\r\\n])"+num+"\\s+"+gen+"\\s+obj\\b(.*?)endobj").matcher(s);if(!obj.find())return new String[]{"","",""};String info=obj.group(1);return new String[]{field(info,"Title"),field(info,"Author"),field(info,"Keywords")};}}catch(Exception e){return new String[]{"","",""};}}
 static String field(String info,String key){try{Matcher m=Pattern.compile("/"+key+"\\s*").matcher(info);if(!m.find())return "";int start=m.end();if(start>=info.length())return "";ByteArrayOutputStream bytes=new ByteArrayOutputStream();char first=info.charAt(start);if(first=='('){int depth=1;for(int i=start+1;i<info.length()&&depth>0;i++){char ch=info.charAt(i);if(ch=='\\'&&i+1<info.length()){ch=info.charAt(++i);if(ch=='n')bytes.write(10);else if(ch=='r')bytes.write(13);else if(ch=='t')bytes.write(9);else if(ch=='b')bytes.write(8);else if(ch=='f')bytes.write(12);else if(ch=='\r'||ch=='\n'){if(ch=='\r'&&i+1<info.length()&&info.charAt(i+1)=='\n')i++;}else if(ch>='0'&&ch<='7'){String oct=""+ch;while(oct.length()<3&&i+1<info.length()&&info.charAt(i+1)>='0'&&info.charAt(i+1)<='7')oct+=info.charAt(++i);bytes.write(Integer.parseInt(oct,8));}else bytes.write(ch);}else if(ch=='('){depth++;bytes.write(ch);}else if(ch==')'){depth--;if(depth>0)bytes.write(ch);}else bytes.write(ch);}}else if(first=='<'&&start+1<info.length()&&info.charAt(start+1)!='<'){int end=info.indexOf('>',start);if(end<0)return "";String hex=info.substring(start+1,end).replaceAll("\\s","");if(hex.length()%2==1)hex+="0";for(int i=0;i<hex.length();i+=2)bytes.write(Integer.parseInt(hex.substring(i,i+2),16));}else return "";byte[] b=bytes.toByteArray();String value=b.length>=2&&(b[0]&255)==254&&(b[1]&255)==255?new String(b,2,b.length-2,"UTF-16BE"):new String(b,"ISO-8859-1");return value.replaceAll("[\\p{Cntrl}]"," ").trim();}catch(Exception e){return "";}}
}
